const NUM_CHROMOSOMES = 400;
const TAUX_MUTATION=0.05;
const CHROMOSOME_LENGTH = 4;
const GENETIC_VALUES = ['A', 'T', 'G', 'C'];
/** Code genetique: [1:en bas, 2:a gauche, 3: en haut, 4: a droite]
 * A:fais pousser bourgeon
 * T: fais pousser feuille
 * C: fais rien graine
 * G: fais rien pousser
 *  */ 

// Créer un tableau de 150 chromosomes 
function hashString(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = (hash << 5) - hash + str.charCodeAt(i);
    hash |= 0; // Convertir en un entier 32 bits
  }
  return Math.abs(hash) % NUM_CHROMOSOMES;
}
function tableauVersDecimal(tableau) {
  const valeurs = { 'A': 0, 'T': 1, 'C': 2, 'G': 3 };
  let decimal = 0;

  // Vérifier si le tableau a exactement 4 éléments
  if (tableau.length !== 4) {
    debugger;
    throw new Error('Le tableau doit contenir exactement 4 éléments');
  }

  // Vérifier si tous les éléments sont des lettres A, T, C ou G
  for (let i = 0; i < tableau.length; i++) {
    const lettre = tableau[i];
    if (!valeurs.hasOwnProperty(lettre)) {
      throw new Error(`L'élément "${lettre}" n'est pas une lettre valide (A, T, C ou G)`);
    }
  }

  // Convertir le tableau en un nombre décimal
  for (let i = 0; i < tableau.length; i++) {
    decimal += valeurs[tableau[i]] * Math.pow(4, tableau.length - i - 1);
  }

  // Normaliser le nombre décimal entre 0 et 1
  return decimal / (Math.pow(4, tableau.length) - 1);
}
export const randomGenome=()=>{

const chromosomes = [];
for (let i = 0; i < NUM_CHROMOSOMES; i++) {
  const chromosome = [];
  for (let j = 0; j < CHROMOSOME_LENGTH; j++) {
    const randomIndex = Math.floor(Math.random() * GENETIC_VALUES.length);
    const geneticValue = GENETIC_VALUES[randomIndex];
    chromosome.push(geneticValue);
  }
  chromosomes.push(chromosome);
}
return chromosomes;
}

export class ADNHandler {
  constructor(sequence) {
      this.adn = sequence;
      this.currentCycle=0;
  }
  setCurrentCycle(newcycle){
    this.currentCycle=newcycle;
  }
  readBool(key){ // return true|false
    const keyIndex = hashString(key);
   const chromosome = this.adn[keyIndex];
   return chromosome[0]==='A'||chromosome[0]==='T';
  }
  readFloat(key){ //return float de 0->1
    const keyIndex = hashString(key);
   const chromosome = this.adn[keyIndex];
   return tableauVersDecimal(chromosome);
  }
  read10(key){ //return int de 1->10
    const asfloat=this.readFloat(key);
   return Math.ceil(asfloat*10);
  }
  mutatedVersion(){
    // return adn mutated
    return mutationADN(this.adn,TAUX_MUTATION);
  }
  getID(forAdn){
    // return id unique for adn
    if(forAdn==null)
      forAdn=this.adn;
    return tableauVersDecimal(forAdn[0])+''+tableauVersDecimal(forAdn[300]);
  }
}
const mutationADN=(adn, tauxMutation) =>{
    const nouvelleADN = [];

    // Parcourir chaque élément de l'ADN
    for (let i = 0; i < adn.length; i++) {
        const gene = adn[i].slice(); // Copier le tableau de gènes actuel

        // Pour chaque gène, déterminer s'il faut le muter
        for (let j = 0; j < CHROMOSOME_LENGTH; j++) {
            if (Math.random() < tauxMutation) { // Vérifier si une mutation se produit
                // Choisir aléatoirement un nouveau nucléotide pour le gène
                const nouveauNucleotide = ['A', 'T', 'C', 'G'][Math.floor(Math.random() * 4)];
                gene[j] = nouveauNucleotide;
            }
        }

        // Ajouter le gène muté à la nouvelle ADN
        nouvelleADN.push(gene);
    }

    return nouvelleADN;
}

export const recombinaisonGenetique = (adn1, adn2)=> {
  const NUM_CHROMOSOMES = adn1.length;
  const CHROMOSOME_LENGTH = adn1[0].length;
  const CROSSOVER_RATE = 0.25; // 15% de chance de croisement par gène

  const enfant = [];
  const enfantChoucou=[];
  for (let c = 0; c < NUM_CHROMOSOMES; c++) {
    // Choix du parent majoritaire pour ce chromosome
    const parentMajoritaire = Math.random() < 0.5 ? adn1 : adn2;
    const parentSecondaire = parentMajoritaire === adn1 ? adn2 : adn1;

    const chromosome = [],chromo2=[];
    for (let g = 0; g < CHROMOSOME_LENGTH; g++) {
      // Cross-over ponctuel
      if (Math.random() < CROSSOVER_RATE) {
        chromosome.push(parentSecondaire[c][g]);
        chromo2.push(parentMajoritaire[c][g])
      } else {
        chromosome.push(parentMajoritaire[c][g]);
        chromo2.push(parentSecondaire[c][g])
      }
    }
    enfant.push(chromosome);
    enfantChoucou.push(chromo2);
  }
  return [enfant, enfantChoucou];
}

export const recombinaisonGenetiqueOld = (adn1, adn2) => {
    // recombine les ADN, on prend chaque chromosome et on le melange
    const newAdns = [];// les parents ont le droit de revenir
    let fecondite=2;
   
    
    const newAdn1=[];
    const newAdn2=[];
    for(let c=0;c<NUM_CHROMOSOMES;c++){
        const chromosome1=adn1[c];
        const chromosome2=adn2[c];
        const splitIndex = Math.floor(Math.random() * chromosome1.length);
        const newChromo1 = chromosome1.slice(0, splitIndex).concat(chromosome2.slice(-splitIndex));
        const newChromo2 = chromosome2.slice(0, splitIndex).concat(chromosome1.slice(-splitIndex));

    // mutation aleatoire 1x/10 sur 1 des child, soit 5% de mutation
    if (Math.random() < 0.05) {
       
        const mutationIndex = Math.floor(Math.random() * newChromo1.length);
        const possibleLetters = 'ATCG';
        let newLetter = possibleLetters[Math.floor(Math.random() * possibleLetters.length)];
        
        newChromo1[mutationIndex] = newLetter;
     }
     newAdn1.push(newChromo1);
     newAdn2.push(newChromo2);
    }
    newAdns.push(newAdn1, newAdn2);

    
    
    return newAdns;
}
